#include <algorithm>
#include <fstream>
#include <istream>
#include <ostream>
#include <vector>
void solveReorder(std::istream& in, std::ostream& out) {
    int n; in >> n;
    std::vector<int> current(n), desired(n), destination(n + 1);
    for (int& cow : current) in >> cow;
    for (int position = 0; position < n; ++position) {
        in >> desired[position]; destination[desired[position]] = position;
    }
    int cycles = 0, longest = -1;
    for (int position = 0; position < n; ++position) {
        if (current[position] == desired[position]) continue;
        int first = current[position], moving = first, length = 0;
        do {
            int target = destination[moving];
            int displaced = current[target];
            current[target] = moving;
            moving = displaced;
            ++length;
        } while (moving != first);
        ++cycles;
        longest = std::max(longest, length);
    }
    out << cycles << ' ' << longest << '\n';
}
int main() {
    std::ifstream in("reorder.in");
    std::ofstream out("reorder.out");
    solveReorder(in, out);
    return 0;
}
