#include <algorithm>
#include <fstream>
#include <istream>
#include <ostream>
#include <utility>
#include <vector>
void solveLazy(std::istream& in, std::ostream& out) {
    int n, k; in >> n >> k;
    std::vector<std::pair<int, int>> patches(n);
    for (auto& patch : patches) in >> patch.second >> patch.first;
    std::sort(patches.begin(), patches.end());
    int left = 0;
    long long sum = 0, best = 0;
    for (int right = 0; right < n; ++right) {
        sum += patches[right].second;
        while (static_cast<long long>(patches[right].first) - patches[left].first > 2LL * k) {
            sum -= patches[left].second;
            ++left;
        }
        best = std::max(best, sum);
    }
    out << best << '\n';
}
int main() {
    std::ifstream in("lazy.in");
    std::ofstream out("lazy.out");
    solveLazy(in, out);
    return 0;
}
