#include <fstream>
#include <istream>
#include <ostream>
#include <string>
#include <utility>
#include <vector>
int regions(const std::vector<std::string>& grid, bool cow) {
    int n = static_cast<int>(grid.size()), count = 0;
    std::vector<std::vector<unsigned char>> seen(n, std::vector<unsigned char>(n, 0));
    const int dr[] = {-1, 0, 1, 0}, dc[] = {0, 1, 0, -1};
    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            if (seen[row][col]) continue;
            ++count;
            std::vector<std::pair<int, int>> stack{{row, col}};
            seen[row][col] = 1;
            while (!stack.empty()) {
                auto cell = stack.back(); stack.pop_back();
                for (int direction = 0; direction < 4; ++direction) {
                    int r = cell.first + dr[direction], c = cell.second + dc[direction];
                    if (r < 0 || r >= n || c < 0 || c >= n || seen[r][c]) continue;
                    char a = grid[cell.first][cell.second], b = grid[r][c];
                    if (a == b || (cow && a != 'B' && b != 'B')) {
                        seen[r][c] = 1; stack.push_back({r, c});
                    }
                }
            }
        }
    }
    return count;
}
void solveCowArt(std::istream& in, std::ostream& out) {
    int n; in >> n;
    std::vector<std::string> grid(n);
    for (std::string& row : grid) in >> row;
    out << regions(grid, false) << ' ' << regions(grid, true) << '\n';
}
int main() {
    std::ifstream in("cowart.in");
    std::ofstream out("cowart.out");
    solveCowArt(in, out);
    return 0;
}
